292: int strendpool_step(SHist *h, int k, int C, const float *x, int n_in, float *y) {
293:     if (k <= 1) { memcpy(y, x, (size_t)C * n_in * sizeof(float)); return n_in; }
294:     int H = 2 * (k - 1);
295:     int L = h->len + n_in;
296:     shist_ensure(h, C, L);
297:     for (int c = 0; c < C; c++)
298:         memcpy(SROW(h, c) + h->len, &x[(size_t)c * n_in], (size_t)n_in * sizeof(float));
299: 
300:     /* causal_trend_pool（零左补齐）：
301:      *   m[t] = max_{u in [t-(k-1), t]} |x[u]|   (u<0 -> 0)
302:      *   y[t] = (1/k) * Σ_{v in [t-(k-1), t]} m[v]  (v<0 -> 0)
303:      * 先用滑窗最大值求 m（O(L*k)），再用前缀和求 y（O(L)）。 */
304:     float *m = (float*)malloc((size_t)L * sizeof(float));
305:     if (!m) { fprintf(stderr, "strendpool_step: OOM L=%d\n", L); exit(1); }
306:     int head = L - n_in;
307:     for (int c = 0; c < C; c++) {
308:         const float *bc = SROW(h, c);
309:         float *yc = &y[(size_t)c * n_in];
310:         for (int t = 0; t < L; t++) {
311:             int lo = t - (k - 1); if (lo < 0) lo = 0;
312:             float mx = 0;
313:             for (int u = lo; u <= t; u++) { float a = fabsf(bc[u]); if (a > mx) mx = a; }
314:             m[t] = mx;
315:         }
316:         /* y[t] = (1/k) Σ_{v=t-k+1}^{t} m[v]（v<0 -> 0）—— 滑窗和 */
317:         acc_t run = 0;
318:         for (int t = 0; t < L; t++) {
319:             run += (acc_t)m[t];
320:             if (t - k >= 0) run -= (acc_t)m[t - k];
321:             if (t >= head) yc[t - head] = (float)(run / (acc_t)k);
322:         }
323:     }
324:     free(m);
325: 
326:     int newlen = (L > H) ? H : L;
327:     for (int c = 0; c < C; c++)
328:         memmove(SROW(h, c), SROW(h, c) + (L - newlen), (size_t)newlen * sizeof(float));
329:     h->len = newlen;
330:     return n_in;
331: }
