403:                 if (getenv("JX_LINFO")) printf("[cu] C=%d dim4=%d rows=%d g=%.6g nx=%.9g q=%d\n", C, dim4, rows, (double)g, (double)cu_nx, qd);
404:                 jx_mac_linear += (double)rows * dim4 * C; jx_n_linear++;
405:                 stage = 1;
406:                 if (qd != 0 && cu_nx == 1.0f) { qok = 1; }
407:                 else if (qd != 0)
408:                   {
409:                     /* nx != 1.0f：融合所依赖的 GRN 简式不成立（实测从未出现），
410:                      * 必须把 p1 重建成浮点结果，退回原路径。 */
411:                     if (norm_fused) { channel_norm_last(&c1, cnw, cnb, B, Tt, C); norm_fused = 0; }
412:                     cu_rebuild_p1(w1, b1, &c1, &p1, alp, ssr, rows, C, dim4, B, Tt);
413:                   }
414:               }
415:           }
416:       }
