431:       const float *b2 = W_(cat_name(pfx, "pw_conv2.bias"));
432:       int done2 = 0;
433:       jx_linear_fuse_t f2;
434:       const jx_linear_fuse_t *fuse2 = NULL;
435:       if (stage == 1)
436:         {
437:           f2.snake_alpha = NULL; f2.ss_rows = NULL;
438:           f2.grn_gamma = qok ? NULL : gg;
439:           f2.grn_beta  = qok ? NULL : gb;
440:           f2.grn_nx = cu_nx;
441:           f2.q_gamma = NULL; f2.q_beta = NULL;
442:           f2.out_q = NULL; f2.out_sc = NULL; f2.out_qdone = NULL;
443:           f2.in_norm_w = NULL; f2.in_norm_b = NULL;
444:           /* r49：in_q 非空 = 输入已由 l1 量化好，l2 跳过整个 prologue */
445:           f2.in_q  = qok ? (const signed char *)p1.d : NULL;
