450:         {
451:           jx_mac_linear += (double)rows * C * dim4; jx_n_linear++;
452:           done2 = 1;
453:         }
454:       else if (stage == 1)
455:         {
456:           /* 融合路径下 p1 里是量化数据，先重建成浮点再补 GRN */
457:           if (norm_fused) { channel_norm_last(&c1, cnw, cnb, B, Tt, C); norm_fused = 0; }
458:           if (qok) { cu_rebuild_p1(w1, b1, &c1, &p1, alp, ssr, rows, C, dim4, B, Tt); qok = 0; }
459:           /* l1+snake 已融合进 p1，只差 GRN：补一次原样 GRN 再走旧 l2 */
460:           grn_last(&p1, gg, gb, B, Tt, dim4);
461:         }
462:       if (done2 == 0)
463:         {
464:           p2 = t_alloc(3, (int[]){B, Tt, C});
