470:           JXP_END(JP_PERMUTE);
471:         }
472:     }
473:     JXP_END(JP_CUOUT);
474:     jx_stage_h("cu.out", y->d, (size_t)y->len * sizeof(float));
475:     y->shape[0] = B; y->shape[1] = C; y->shape[2] = Tt; y->len = B*C*Tt;
476:     t_free(&c1); t_free(&p1); if (p2_ok) { t_free(&p2); }
477:     free(ssr); free(f2s);
668: static void legacy_unit_core(const T *x, T *y, const char *pfx, int dil) {
669:     /* LegacyUnit(dim): Snake -> Conv(k=7,p=3*dil) -> Snake -> Conv(k=1) ; residual add inside caller.
670:        dilation comes from ResidualLegacyUnit(dilation=1/3/9); padding = (k-1)*dil//2 = 3*dil. */
671:     int B = x->shape[0], C = x->shape[1], Tt = x->shape[2];
672:     /* 2026-09-14 第三十三轮：原来是 t_copy + snake1d 两趟整张量往返，
673:      * 合成一趟 snake1d_copy（数值逐位相同）。 */
674:     T s0 = t_alloc(3, (int[]){B, C, Tt});
675:     snake1d_copy(&s0, x, W_(cat_name(pfx, "block.0.alpha")));
676:     /* 2026-09-13 第九轮：这里原来有两次纯搬运，合计每调用 4 个张量往返
677:      * （T=16032 时约 4MB，实测 ~90ms/次）：
678:      *   1) conv1d_d 写进 c1 后再 t_copy 到 s1 —— conv1d_d 已经设好
679:      *      shape[0..2]/len，snake1d 直接吃 c1 就行，复制毫无必要；
680:      *   2) 末层 conv1d 写进 c2 后再逐元素抄进 y —— 直接让 conv1d 写 y
681:      *      即可（y->len 恰好等于 need，不会触发 realloc）。
682:      * 两者都不改任何数值。 */
683:     T c1 = t_alloc(3, (int[]){B, C, 0});
684:     /* 第三十三轮：block.2 的 snake 折进 conv1d_d 的 epilogue（省掉一趟整张量往返）。 */
685:     conv1d_d_snake(W_(cat_name(pfx, "block.1.weight")), W_(cat_name(pfx, "block.1.bias")),
686:                    &s0, &c1, C, C, 7, 1, 3 * dil, 1, Tt, dil,
687:                    W_(cat_name(pfx, "block.2.alpha")));
688:     conv1d(W_(cat_name(pfx, "block.3.weight")), W_(cat_name(pfx, "block.3.bias")), &c1, y, C, C, 1, 1, 0, 1, Tt);
689:     y->shape[0] = B; y->shape[1] = C; y->shape[2] = Tt; y->len = B*C*Tt;
690:     t_free(&s0); t_free(&c1);
691: }
