719: void first_block(const T *x, T *y) {
720:     JXP_BEG(JP_FIRSTBLOCK);
721:     int B = x->shape[0], Tt = x->shape[2]; const int Co = ENC_DIMS[0];
722:     int W = chunk_width();
723:     y->ndim = 3; y->shape[0] = B; y->shape[1] = Co; y->shape[2] = Tt;
724:     y->len = B * Co * Tt;
725:     if (W <= 0 || Tt <= W) {
726:         if (first_block_core(x, y) != 0) {
727:             jx_conv_skip++;
728:             printf("[FB] first_block_core OOM，跳过\n");
729:             memset(y->d, 0, (size_t)y->len * sizeof(float));
730:         }
825:         int save_from = -1;
826:         for (int t0 = 0; t0 < Tt; t0 += W) {
827:             int t1 = t0 + W; if (t1 > Tt) t1 = Tt;
828:             int a = t0 - JX_CU_HALO; if (a < 0) a = 0;
829:             int e = t1 + JX_CU_HALO; if (e > Tt) e = Tt;
830:             int w = e - a;
831:             T xs = t_alloc(3, (int[]){1, C, w});
832:             {
833:                 JXP_BEG(JP_MISC);
834:                 jx_glue_g_t gg; gg.src = x; gg.dst = xs.d; gg.save = save;
835:                 gg.C = C; gg.Tt = Tt; gg.bi = bi; gg.a = a; gg.w = w;
836:                 gg.saved_from = save_from; gg.H = JX_CU_HALO; gg.split_t = 0;
837:                 jx_pf_run_min(C, jx_glue_gather, &gg, 2);
838:                 JXP_END(JP_MISC);
839:             }
840:             T ys = t_alloc(3, (int[]){1, C, w});
841:             conv_unit_core(&xs, &ys, pfx);
842:             int ns = t1 - JX_CU_HALO; if (ns < t0) ns = t0;
843:             {
844:                 JXP_BEG(JP_MISC);
845:                 jx_glue_v_t gv; gv.src = x->d; gv.save = save; gv.C = C; gv.Tt = Tt;
846:                 gv.bi = bi; gv.ns = ns; gv.n = t1 - ns; gv.H = JX_CU_HALO;
847:                 jx_pf_run_min(C, jx_glue_save, &gv, 2);
848:                 JXP_END(JP_MISC);
849:             }
850:             save_from = ns;
851:             {
852:                 JXP_BEG(JP_MISC);
853:                 jx_glue_s_t gs; gs.dst = x->d; gs.src = ys.d; gs.C = C; gs.Tt = Tt;
854:                 gs.bi = bi; gs.t0 = t0; gs.n = t1 - t0; gs.off = t0 - a; gs.stride = w; gs.add = 1;
855:                 jx_pf_run_min(C, jx_glue_scatter, &gs, 2);
856:                 JXP_END(JP_MISC);
857:             }
858:             t_free(&xs); t_free(&ys);
859:         }
860:     }
861:     free(save);
862:     JXP_END(JP_CONVUNIT);
863: }
