865: /* ============================ LegacyUnit 时间分块累加 ============================ */
866: /* 解码器末段 decoder.blocks.13 有 3 个 ResidualLegacyUnit。整段展开时，cur / lu /
867:  * legacy_unit 内部的 s0 与 c1 四块 [B,16,T] 会同时活着：2 秒音频 T=32064 时每块
868:  * 2.05MB、合计 8.2MB，已经超过 PSRAM 堆总量（~8.5MB）。结果是 conv1d_d 的
869:  * realloc 拿不到 2MB 连续块 -> 卷积被跳过 -> 整段输出作废（板端实测 3 次 [CONV]）。
870:  *
871:  * LegacyUnit 的时间感受野只有 3*dil <= 27 个样点（两端 Snake 与末尾 k=1 卷积都是
872:  * 逐点算子），所以按时间切块、每块左右各带 H = 3*dil 样点 halo 即可：
873:  *   - 中间块只把 [t0,t1) 写回，halo 区结果直接丢弃；
874:  *   - 分块内部 conv1d_d 的零填充只影响距块边界 <= pad 的输出，正好落在丢弃区；
875:  * 于是与整段计算逐位一致（这是 blocks.c 里 first_block / conv_unit 早就在用的做法）。
876:  *
877:  * 同时省掉一整块 [B,16,T]：结果就地累加进 x，不再单独分配 lu 再逐元素相加。
878:  * 块宽沿用 JX_CHUNK（默认 2048）；JX_CHUNK=0 关闭分块，退回整段路径（主机对照用）。 */
879: #define JX_LU_HALO 32
880: 
881: /* 整段路径：只额外要 2 块 [B,C,Tt]。s0 的内容在最后一步之前就用完了，
882:  * 直接把它那块缓冲改当 1x1 卷积的输出，省掉第 3 块。
883:  * 返回 0 = 成功（x 已就地累加），1 = 内存不够（x 一个字节都没动）。 */
884: static int legacy_unit_add_full(T *x, const char *pfx, int dil)
885: {
886:     int B = x->shape[0], C = x->shape[1], Tt = x->shape[2];
887:     T s0 = t_alloc(3, (int[]){B, C, Tt});
888:     if (s0.d == NULL) { return 1; }
889:     snake1d_copy(&s0, x, W_(cat_name(pfx, "block.0.alpha")));
890:     T c1 = t_alloc(3, (int[]){B, C, Tt});
891:     if (c1.d == NULL) { t_free(&s0); return 1; }
892:     conv1d_d_snake(W_(cat_name(pfx, "block.1.weight")), W_(cat_name(pfx, "block.1.bias")),
893:                    &s0, &c1, C, C, 7, 1, 3 * dil, 1, Tt, dil,
894:                    W_(cat_name(pfx, "block.2.alpha")));
895:     T out = s0; s0.d = NULL; s0.len = 0;      /* 所有权交接，t_free(&s0) 变成空操作 */
896:     conv1d(W_(cat_name(pfx, "block.3.weight")), W_(cat_name(pfx, "block.3.bias")),
897:            &c1, &out, C, C, 1, 1, 0, 1, Tt);
898:     {
899:         JXP_BEG(JP_MISC);
900:         { jx_ew_t ew; ew.a = out.d; ew.b = NULL; ew.y = x->d;
901:           ew.n = x->len; ew.mode = 1;
902:           jx_pf_run_min(ew.n, jx_ew_range, &ew, 2); }
903:         JXP_END(JP_MISC);
904:     }
905:     t_free(&out); t_free(&c1);
906:     return 0;
907: }
