909: /* 分块路径：每块额外只要 2 个小缓冲（约为整段的 W/Tt）。 */
910: static void legacy_unit_add_chunked(T *x, const char *pfx, int dil, int W, int H)
911: {
912:     int B = x->shape[0], C = x->shape[1], Tt = x->shape[2];
913:     /* 就地在 x 上累加时，本块写回 [t0,t1)，而下一块要拿 [t1-H, t1) 当左 halo ——
914:      * 那 H 个样点已经被本块改过。所以写之前先把“加之前”的原值留一份，下一块读
915:      * halo 时用它。做法与 conv_unit_add() 完全一致。 */
916:     float *save = NULL;
917:     if (W > H && H > 0) { save = (float*)malloc((size_t)C * H * sizeof(float)); }
918:     if (save == NULL)
919:       {
920:         /* 连 2KB 的保存区都拿不到：只能退回整段，失败就报出来，别静默出错 */
921:         if (legacy_unit_add_full(x, pfx, dil) != 0)
922:           {
923:             jx_conv_skip++;
924:             printf("[LU] 内存不足，跳过本次 legacy 残差\n");
925:           }
926:         return;
927:       }
928:     for (int bi = 0; bi < B; bi++)
929:       {
930:         int saved_from = -1;
931:         for (int t0 = 0; t0 < Tt; t0 += W)
932:           {
933:             int t1 = t0 + W; if (t1 > Tt) { t1 = Tt; }
934:             int a  = t0 - H; if (a < 0)   { a  = 0;  }
935:             int e  = t1 + H; if (e > Tt)  { e  = Tt; }
936:             int w  = e - a;
937:             T xs = t_alloc(3, (int[]){1, C, w});
938:             T ys = t_alloc(3, (int[]){1, C, w});
939:             if (xs.d == NULL || ys.d == NULL)
940:               {
941:                 t_free(&xs); t_free(&ys); free(save);
942:                 jx_conv_skip++;
943:                 printf("[LU] 分块缓冲分配失败，跳过本次 legacy 残差\n");
944:                 return;
945:               }
946:             {
947:                 JXP_BEG(JP_MISC);
948:                 jx_glue_g_t gg; gg.src = x; gg.dst = xs.d; gg.save = save;
949:                 gg.C = C; gg.Tt = Tt; gg.bi = bi; gg.a = a; gg.w = w;
950:                 gg.saved_from = saved_from; gg.H = H; gg.split_t = 0;
