    text=buf.decode('utf-8',errors='replace')
    assert not any(v in text for v in ['PANIC','assertion failed','sa_alloc overflow','OOM']),cmd
    records.append({'command':cmd,'host_s':time.monotonic()-start,'output':text})
    return text
