            print('\nVARIANT_COMPLETED',variant,flush=True)
        for key in ['JX_D_FUSE','JX_D_LEGACY','JX_D_NORMCACHE','JX_D_DUMP']:command('unset '+key,log)
        command('ps',log);command('free',log);command('jixun ui status',log)
finally:
    port.close();(P/('board_'+name+'.json')).write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
