static void dpb_fill_q(float *tab, int W, int heads, int H,
                       const int8_t *w0, const float *sc0, const float *b0,
                       const int8_t *w1, const float *sc1, const float *b1,
                       const int8_t *w2, const float *sc2, const float *b2) {
