      "addi %[O], %[O], 4\n\t"
      "addi %[C], %[C], -1\n\t"
      "bnez %[C], 1b\n\t"
        : [Q] "+r"(q), [K] "+r"(k), [O] "+r"(o), [C] "+r"(c), [T] "=&r"(t)
