   * 这个 for(;;) 退不出去，整轮发送永久挂住。
   * 改成和 lora_wait_busy 一样的固定 1 ms 计数超时。 */
  for (uint32_t tick = 0; ; tick++)
    {
      uint16_t irq = 0;

      if (sx_get_irq(&irq) == 0)
        {
          if (irq & SX_IRQ_TX_DONE)
