              if (lora_wait_busy(100) == 0)
                {
                  sx_clear_irq(0xFFFF);
                }

              return 0;
            }

          if (irq & SX_IRQ_TIMEOUT)
            {
              sx_clear_irq(0xFFFF);
              return -4;
            }
        }
