static void srx_unpack(const uint8_t *in, int n, int64_t *tok)
{
  int i;
  int b;

  for (i = 0; i < n; i++)
    {
      uint32_t v = 0;
      for (b = 0; b < 18; b++)
        {
          int bit = i * 18 + b;
          if ((in[bit >> 3] >> (bit & 7)) & 1u)
            {
              v |= (uint32_t)1u << b;
            }
        }
      tok[i] = (int64_t)(v & 0x3FFFFu);
    }
}


