        else if (tick - last_feed > max_feed_gap) max_feed_gap = tick - last_feed;
        last_feed = tick;
      }
      if (jx_voice_stream_play_pcm(chunk, take) != 0)
        {
          pthread_mutex_lock(&pb->lock);
          pb->failed = 1;
          pthread_cond_broadcast(&pb->cond);
          pthread_mutex_unlock(&pb->lock);
          break;
        }
