#!/usr/bin/env python3
"""在 ESP32 COM3 上跑 AMR-NB 4.75k 编解码，计算 PESQ-NB 和 STOI。"""
import argparse
import struct
import sys
import time

import numpy as np
import soundfile as sf
import serial
from scipy.signal import resample_poly
from pesq import pesq
from pystoi import stoi


def read_some(s, timeout=30.0):
    deadline = time.time() + timeout
    while time.time() < deadline:
        data = s.read(4096)
        if data:
            return data
    raise TimeoutError("串口读超时")


def read_exact(s, n, timeout=30.0):
    buf = bytearray()
    deadline = time.time() + timeout
    while len(buf) < n:
        if time.time() > deadline:
            raise TimeoutError(f"需要 {n} 字节，只收到 {len(buf)}")
        data = s.read(n - len(buf))
        if data:
            buf += data
    return bytes(buf)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("wav")
    ap.add_argument("--port", default="COM3")
    ap.add_argument("--out", default=r"E:\codex\place\pl1\2026-10-15\ni-h\esp32_amr\host\decoded.wav")
    ap.add_argument("--seconds", type=float, default=2.0)
    args = ap.parse_args()

    audio, sr = sf.read(args.wav, dtype="int16", always_2d=True)
    audio = audio[:, 0]
    if sr != 8000:
        g = np.gcd(sr, 8000)
        audio = resample_poly(audio.astype(np.float64), 8000 // g, sr // g)
        audio = np.clip(np.round(audio), -32768, 32767).astype(np.int16)
    n = min(len(audio), int(8000 * args.seconds))
    n -= n % 160
    audio = audio[:n]
    if n == 0:
        raise SystemExit("音频太短")

    s = serial.Serial(args.port, 921600, timeout=1)
    s.dtr = False
    s.rts = False
    try:
        buf = b""
        deadline = time.time() + 10
        while b"AMR_BENCH_READY" not in buf and time.time() < deadline:
            data = s.read(256)
            if data:
                buf += data
        if b"AMR_BENCH_READY" not in buf:
            print("没看到 AMR_BENCH_READY，收到的内容:", repr(buf[:200]), file=sys.stderr)

        t0 = time.time()
        s.write(b"AMRB" + struct.pack("<I", n) + audio.tobytes())
        s.flush()
        t_send = time.time() - t0

        buf = b""
        deadline = time.time() + 30
        while b"AMRO" not in buf and time.time() < deadline:
            data = s.read(4096)
            if data:
                buf += data
        idx = buf.find(b"AMRO")
        if idx < 0:
            raise TimeoutError("没收到 AMRO 返回头")
        rest = buf[idx + 4:]
        while len(rest) < 20:
            rest += read_some(s)
        ns, frames, amr_bytes, enc_us, dec_us = struct.unpack("<IIIII", rest[:20])
        if ns == 0 or ns > 32000:
            raise ValueError(f"设备返回的样本数异常: {ns}")
        pcm = rest[20:]
        need = ns * 2 - len(pcm)
        if need > 0:
            pcm += read_exact(s, need)
        out = np.frombuffer(pcm[: ns * 2], dtype="<i2")

        sf.write(args.out, out, 8000)

        m = min(len(audio), len(out))
        ref = audio[:m].astype(np.float64)
        deg = out[:m].astype(np.float64)
        pesq_score = pesq(8000, ref, deg, "nb")
        stoi_score = stoi(ref, deg, 8000, extended=False)
        bitrate = amr_bytes * 8 / (frames * 0.020)

        print(f"file={args.wav}")
        print(f"samples={ns} frames={frames} amr_bytes={amr_bytes} bitrate={bitrate:.0f} bps")
        print(f"enc_ms={enc_us/1000:.2f} dec_ms={dec_us/1000:.2f} send_s={t_send:.2f}")
        print(f"pesq_nb={pesq_score:.4f} stoi={stoi_score:.4f}")
        print(f"decoded={args.out}")
    finally:
        s.close()


if __name__ == "__main__":
    main()
