/* 2026-10-12 诊断：bench 用固定合成音频跑完整编解码，加打印解码输出统计
 * 便于直接对比 int8 / float 两条路径的数值（JX_DUMPB 时把 rec 以 hex 回传）。 */
static void jx_dump_hex(const char *tag, const int16_t *p, int n);

static int jx_cmd_bench(int argc, char *argv[])
{
  int secs = jx_parse_seconds(argc, argv, 5, 60);
  int n    = secs * JX_PCM_RATE;

  printf("=== 极讯 Codec 单板算力基准 (码率 %s) ===\n", jx_rate_name());
  jx_print_wt();

  int16_t *pcm = (int16_t *)malloc(sizeof(int16_t) * (size_t)n);
  if (pcm == NULL)
    {
      printf("[ERR] 分配 %d 样本失败\n", n);
      return 1;
    }

  jx_gen_pcm(pcm, n, 0x2468ace1u);
  jx_print_mem("基准前");

  int64_t *bidx = NULL; int bntok = 0, bTt = 0; float *brec = NULL;
  double t0 = jx_now_ms();
  int rc = jx_run_once(pcm, n, &bidx, &bntok, &bTt, &brec);
  double t1 = jx_now_ms();

  if (rc == 0 && brec != NULL)
    {
      float mn = 1e9f, mx = -1e9f;
      double su = 0.0, sq = 0.0;
      for (int i = 0; i < n; i++)
        {
          float v = brec[i];
          if (v < mn) { mn = v; }
          if (v > mx) { mx = v; }
          su += (double)v;
          sq += (double)v * (double)v;
        }
      printf("  [rec] min=%.5f max=%.5f mean=%.5f rms=%.5f\n",
             (double)mn, (double)mx, su / (double)n, sqrt(sq / (double)n));
      if (jx_env_on("JX_DUMPB", 0))
        {
          int16_t *d16 = (int16_t *)malloc(sizeof(int16_t) * (size_t)n);
          if (d16 != NULL)
            {
              for (int i = 0; i < n; i++)
                {
                  d16[i] = jx_round_s16((double)brec[i]);
                }
              jx_dump_hex("bench", d16, n);
              free(d16);
            }
        }
    }
  free(bidx);
  free(brec);

  jx_print_mem("基准后");
  printf("  含分配/释放的墙钟总时间: %.1f ms\n", t1 - t0);

  free(pcm);
  return rc;
}

